INSERT IGNORE INTO `g2g_product_profiles` (`id`, `sub_institute_id`, `product_name`, `description`, `problems_solved`, `features`, `target_industries`, `target_company_types`, `target_company_size`, `target_markets`, `ideal_customer_profile`, `keywords`, `excluded`, `competitors`, `research_enabled`, `research_frequency`, `schedule_time`, `recency_days`, `updated_by`, `created_at`, `updated_at`) VALUES ('1', '6', 'TRIZ Innovation — AI, Enterprise Intelligence & Digital Solutions', 'TRIZ Innovation develops AI-powered business intelligence, enterprise knowledge systems, education technology, and custom digital solutions. Its solution portfolio includes G2G business opportunity intelligence, Enterprise Brain for organizational knowledge and decision intelligence, and Scholar Clone education technology. The focus is on helping organizations turn data, information, and business signals into actionable insights, improved workflows, and better-informed decisions.', 'Business information scattered across documents, databases, websites, and applications; difficulty identifying relevant business opportunities, tenders, partnerships, and market developments; limited visibility into organizational knowledge, operational signals, and actionable insights; manual analysis and repetitive information-processing workflows; education institutions\' need for integrated digital learning, academic workflows, and AI-enabled capabilities.', 'AI/LLM-powered information analysis and summarization; business signal discovery, research, and opportunity intelligence; enterprise data ingestion and knowledge extraction; organizational intelligence, evidence-based insights, and recommendations; workflow automation and AI-assisted decision support; education technology, LMS, academic analytics, and learning intelligence; custom AI integrations, APIs, and software development.', '[\"Education\",\"Information Technology\",\"Software\",\"Enterprise Technology\",\"Business Services\",\"Manufacturing\",\"Healthcare\",\"Government\",\"Professional Services\"]', '[\"Schools\",\"school groups\",\"education networks\",\"SMEs\",\"mid-market companies\",\"large enterprises\",\"technology companies\",\"service providers\",\"government departments\",\"and organizations seeking AI\",\"data intelligence\",\"or workflow automation.\"]', 'Small and medium businesses, mid-market organizations, large enterprises, multi-location organizatio', '[\"India\",\"Gujarat\",\"Maharashtra\",\"Delhi NCR\",\"Karnataka\",\"Telangana\",\"and other Indian states. International markets: opportunities in the Middle East\",\"Southeast Asia\",\"Europe\",\"and North America where relevant.\"]', 'An organization with a clear need for AI-enabled business intelligence, enterprise data integration, knowledge management, opportunity discovery, workflow automation, or digital education solutions. Priority accounts have identifiable business needs, an active project or buying trigger, a relevant decision-maker, and a realistic implementation opportunity.', '[\"AI solutions\",\"artificial intelligence\",\"generative AI\",\"enterprise AI\",\"business intelligence\",\"enterprise intelligence\",\"knowledge management\",\"data intelligence\",\"AI agents\",\"workflow automation\",\"digital transformation\",\"enterprise software\",\"LMS\",\"education technology\",\"school ERP\",\"learning analytics\",\"government tenders\",\"RFP\",\"procurement\",\"digital learning\",\"AI implementation\",\"strategic partnerships\"]', '[\"Gambling\",\"adult entertainment\",\"tobacco\",\"unrelated consumer-only retail\",\"and opportunities with no identifiable relevance to AI\",\"enterprise software\",\"business intelligence\",\"automation\",\"or education technology.\"]', '[\"Enterprise AI\",\"BI tools\",\"AI consultancies\",\"LMS and school ERP providers\"]', '0', 'daily', '10:00', '30', '28', '2026-10-01 11:04:20', '2026-10-01 11:04:20');
