INSERT IGNORE INTO `g2g_company_opportunities` (`id`, `sub_institute_id`, `company_id`, `research_run_id`, `ingestion_source_id`, `product_name`, `title`, `category`, `signal_kind`, `observed_event`, `why_indicates_need`, `product_fit`, `relevant_offer_id`, `relevant_offer_name`, `recommended_action`, `priority`, `urgency`, `feed_section`, `qualification`, `confidence`, `review_status`, `review_notes`, `sources`, `confirmed_facts`, `unverified_claims`, `source_published_at`, `event_date`, `fingerprint`, `first_discovered_at`, `last_verified_at`, `reviewed_by`, `reviewed_at`, `created_at`, `updated_at`) VALUES ('1', '6', '1', '3', NULL, 'TRIZ Innovation — AI, Enterprise Intelligence & Digital Solutions', 'NEC India and WingArc1st expand partnership to bring data empowerment and analytics solutions to India', 'technology_change', 'opportunity', 'NEC India and WingArc1st announced expansion of their strategic collaboration in India via a Master Distribution Agreement, targeting Enterprise, Financial Services, Manufacturing and Public Sector/Government with data and analytics technologies.', 'A newly signed distribution agreement to grow data/analytics and business-intelligence offerings in India implies demand for complementary AI, data-intelligence and knowledge-management capabilities to deliver to enterprise and government clients.', 'TRIZ Innovation\'s AI-powered business intelligence, enterprise data ingestion/knowledge extraction and workflow automation could complement NEC India\'s data empowerment portfolio for enterprise and government customers.', NULL, NULL, 'Research NEC India\'s data/analytics portfolio and partner ecosystem, then explore whether TRIZ AI/BI capabilities could be positioned as a complementary offering or integration.', 'Medium', 'Within 90 days', 'market_intelligence', 'Relevant Requirement Found', 'Medium', 'New', NULL, '[{\"url\":\"https:\\/\\/www.passionateinmarketing.com\\/nec-india-and-wingarc1st-expand-strategic-partnership-to-bring-data-empowerment-solutions-to-india\",\"title\":\"NEC India and WingArc1st Expand Strategic Partnership\",\"published_at\":\"2026-09-22\",\"excerpt\":\"NEC Corporation India Pvt. Ltd. and WingArc1st Inc. today announced the expansion of their strategic collaboration in India following the execution of a Master Distribution Agreement (MDA)\",\"retrieved_at\":\"2026-10-01T12:54:17+00:00\",\"page_fetched\":false}]', '[\"NEC India and WingArc1st announced expansion of their strategic collaboration in India following a Master Distribution Agreement.\",\"The partnership will address opportunities across Enterprise, Financial Services, Manufacturing, and Public Sector\\/Government.\"]', '[\"Whether NEC India is seeking third-party AI or BI vendors\",\"Any budget, procurement process or timeline\"]', '2026-09-22', '2026-09-22', 'a120c218d72dded4e6c9efa6a97ff0e1dfc77707abbd3b91113ac4b2c20d6723', '2026-10-01 12:54:57', '2026-10-01 12:54:57', NULL, NULL, '2026-10-01 12:54:57', '2026-10-01 12:54:57');
INSERT IGNORE INTO `g2g_company_opportunities` (`id`, `sub_institute_id`, `company_id`, `research_run_id`, `ingestion_source_id`, `product_name`, `title`, `category`, `signal_kind`, `observed_event`, `why_indicates_need`, `product_fit`, `relevant_offer_id`, `relevant_offer_name`, `recommended_action`, `priority`, `urgency`, `feed_section`, `qualification`, `confidence`, `review_status`, `review_notes`, `sources`, `confirmed_facts`, `unverified_claims`, `source_published_at`, `event_date`, `fingerprint`, `first_discovered_at`, `last_verified_at`, `reviewed_by`, `reviewed_at`, `created_at`, `updated_at`) VALUES ('2', '6', '2', '3', NULL, 'TRIZ Innovation — AI, Enterprise Intelligence & Digital Solutions', 'Vaia expands its AI intelligence platform into the US market for financial institutions', 'expansion', 'opportunity', 'Vaia, an AI-powered intelligence platform for financial institutions, announced expansion into the United States to serve banks, investment firms, wealth managers and family offices, building local technology, product and commercial teams.', 'Rapid international expansion with new local product and commercial teams typically increases demand for scalable enterprise AI, data intelligence and knowledge-system capabilities.', 'TRIZ Innovation\'s enterprise intelligence, knowledge extraction and AI-assisted decision support capabilities align with Vaia\'s AI intelligence platform for financial workflows.', NULL, NULL, 'Monitor Vaia\'s US build-out and assess whether TRIZ AI/enterprise-intelligence capabilities could support its platform or delivery needs.', 'Medium', 'Monitoring', 'watchlist', 'Monitoring', 'Medium', 'New', NULL, '[{\"url\":\"https:\\/\\/www.tribuneindia.com\\/news\\/business\\/vaia-expands-into-the-us-market-bringing-its-ai-intelligence-platform-to-american-financial-institutions\",\"title\":\"Vaia Expands into the US Market, Bringing Its AI Intelligence Platform to American Financial Institutions - The Tribune\",\"published_at\":\"2026-09-24\",\"excerpt\":\"Vaia, an AI-powered intelligence platform for financial institutions, has announced its expansion into the United States to serve banks, investment firms, wealth managers and family offices\",\"retrieved_at\":\"2026-10-01T12:54:17+00:00\",\"page_fetched\":false}]', '[\"Vaia announced expansion into the United States to serve banks, investment firms, wealth managers and family offices.\",\"Vaia said it is building local technology, product and commercial teams in the US.\"]', '[\"Whether Vaia needs external AI or enterprise-intelligence vendors\",\"Any budget or procurement plans\"]', '2026-09-24', '2026-09-24', 'd27028d145950faebda4f4c540df520853d69614f989b13b48a81f7afa6d5509', '2026-10-01 12:54:57', '2026-10-01 12:54:57', NULL, NULL, '2026-10-01 12:54:57', '2026-10-01 12:54:57');
INSERT IGNORE INTO `g2g_company_opportunities` (`id`, `sub_institute_id`, `company_id`, `research_run_id`, `ingestion_source_id`, `product_name`, `title`, `category`, `signal_kind`, `observed_event`, `why_indicates_need`, `product_fit`, `relevant_offer_id`, `relevant_offer_name`, `recommended_action`, `priority`, `urgency`, `feed_section`, `qualification`, `confidence`, `review_status`, `review_notes`, `sources`, `confirmed_facts`, `unverified_claims`, `source_published_at`, `event_date`, `fingerprint`, `first_discovered_at`, `last_verified_at`, `reviewed_by`, `reviewed_at`, `created_at`, `updated_at`) VALUES ('3', '6', '3', '3', NULL, 'TRIZ Innovation — AI, Enterprise Intelligence & Digital Solutions', 'Brahma AI raises $150 million at $2 billion valuation to accelerate enterprise AI platform', 'funding', 'opportunity', 'Prime Focus-backed Brahma AI raised $150 million at a $2 billion valuation, with capital to accelerate development and global commercialisation of its enterprise AI platform, and received a further $100 million of investor demand.', 'A large funding round earmarked for enterprise AI platform development and global commercialisation can drive demand for AI, data-intelligence and knowledge-management capabilities and partners.', 'TRIZ Innovation\'s enterprise AI, knowledge extraction and workflow automation offerings could be relevant to Brahma AI\'s enterprise AI platform build-out.', NULL, NULL, 'Track Brahma AI\'s platform roadmap and commercialisation plans to identify potential AI capability or integration alignment.', 'Medium', 'Monitoring', 'watchlist', 'Monitoring', 'Medium', 'New', NULL, '[{\"url\":\"https:\\/\\/www.storyboard18.com\\/digital\\/prime-focus-backed-brahma-ai-raises-150-million-at-2-billion-valuation-eyes-global-expansion-111171.htm\",\"title\":\"Prime Focus-backed Brahma AI raises $150 million at $2 billion valuation, eyes global expansion - Storyboard18\",\"published_at\":\"2026-09-23\",\"excerpt\":\"The latest funding gives Brahma AI capital to accelerate development and global commercialisation of its enterprise AI platform\",\"retrieved_at\":\"2026-10-01T12:54:17+00:00\",\"page_fetched\":false}]', '[\"Brahma AI raised $150 million at a $2 billion valuation.\",\"The funding gives Brahma AI capital to accelerate development and global commercialisation of its enterprise AI platform.\"]', '[\"Whether Brahma AI is seeking external AI vendors or partners\",\"Any specific technology requirements or budgets\"]', '2026-09-23', '2026-09-23', '186d08baddd055708ad965b590291896276475bdfd726339b481b56838c1062e', '2026-10-01 12:54:57', '2026-10-02 05:07:11', NULL, NULL, '2026-10-01 12:54:57', '2026-10-02 05:07:11');
INSERT IGNORE INTO `g2g_company_opportunities` (`id`, `sub_institute_id`, `company_id`, `research_run_id`, `ingestion_source_id`, `product_name`, `title`, `category`, `signal_kind`, `observed_event`, `why_indicates_need`, `product_fit`, `relevant_offer_id`, `relevant_offer_name`, `recommended_action`, `priority`, `urgency`, `feed_section`, `qualification`, `confidence`, `review_status`, `review_notes`, `sources`, `confirmed_facts`, `unverified_claims`, `source_published_at`, `event_date`, `fingerprint`, `first_discovered_at`, `last_verified_at`, `reviewed_by`, `reviewed_at`, `created_at`, `updated_at`) VALUES ('4', '6', '4', '3', NULL, 'TRIZ Innovation — AI, Enterprise Intelligence & Digital Solutions', 'Keystone launches India business with Bengaluru as first hub, plans to hire and expand workforce', 'expansion', 'opportunity', 'Keystone, a global advisory firm, announced it is establishing Keystone India with Bengaluru as its first hub and plans to hire talent and expand its workforce over the next two years, helping clients navigate AI disruption and India\'s regulatory environment.', 'A new India operation focused on helping clients navigate AI disruption may require AI-enabled knowledge systems, business intelligence and workflow automation to deliver advisory services at scale.', 'TRIZ Innovation\'s enterprise knowledge systems, business signal discovery and AI-assisted decision support could support Keystone India\'s advisory delivery.', NULL, NULL, 'Research Keystone India\'s service lines and assess whether TRIZ AI/knowledge-management capabilities could support their advisory workflows.', 'Low', 'Monitoring', 'watchlist', 'Needs Verification', 'Low', 'New', NULL, '[{\"url\":\"https:\\/\\/www.prnewswire.com\\/news-releases\\/keystone-to-launch-india-business-with-bengaluru-as-first-hub-plans-to-hire-talent--increase-workforce-over-next-two-years-302889844.html\",\"title\":\"Keystone To Launch India Business With Bengaluru As First Hub, Plans To Hire Talent & Increase Workforce Over Next Two Years - PR Newswire\",\"published_at\":\"2026-09-25\",\"excerpt\":\"Keystone, a global advisory firm that guides the most critical technology and science-based platforms and ecosystems, today announced it is establishing Keystone India, with Bengaluru as its first hub in the country.\",\"retrieved_at\":\"2026-10-01T12:54:17+00:00\",\"page_fetched\":false}]', '[\"Keystone announced it is establishing Keystone India with Bengaluru as its first hub.\",\"The company plans to hire talent and expand its workforce in India over the next two years.\"]', '[\"Whether Keystone India needs AI, BI or knowledge-management tools\",\"Any budget or vendor evaluation\"]', '2026-09-25', '2026-09-25', 'f5b82645995d6a6dec41cc35c8c9d4b79741679ceb2cec2037cdd6ebce6d216b', '2026-10-01 12:54:57', '2026-10-01 12:54:57', NULL, NULL, '2026-10-01 12:54:57', '2026-10-01 12:54:57');
INSERT IGNORE INTO `g2g_company_opportunities` (`id`, `sub_institute_id`, `company_id`, `research_run_id`, `ingestion_source_id`, `product_name`, `title`, `category`, `signal_kind`, `observed_event`, `why_indicates_need`, `product_fit`, `relevant_offer_id`, `relevant_offer_name`, `recommended_action`, `priority`, `urgency`, `feed_section`, `qualification`, `confidence`, `review_status`, `review_notes`, `sources`, `confirmed_facts`, `unverified_claims`, `source_published_at`, `event_date`, `fingerprint`, `first_discovered_at`, `last_verified_at`, `reviewed_by`, `reviewed_at`, `created_at`, `updated_at`) VALUES ('5', '6', '5', '3', NULL, 'TRIZ Innovation — AI, Enterprise Intelligence & Digital Solutions', 'RSK Business Solutions to showcase practical AI applications at Dubai AI Festival 2026', 'technology_change', 'insight', 'RSK Business Solutions announced participation in Dubai AI Festival 2026 to demonstrate AI applications for operational and business requirements, with discussions covering risk, knowledge systems and operational efficiency.', 'A consultancy positioning around practical AI, knowledge systems and operational efficiency may seek complementary AI, knowledge-management and workflow automation capabilities.', 'TRIZ Innovation\'s enterprise knowledge systems, AI-assisted decision support and workflow automation align with RSK\'s stated focus on knowledge systems and operational efficiency.', NULL, NULL, 'Monitor RSK\'s Dubai AI Festival activity and evaluate potential collaboration or capability alignment in AI knowledge systems.', 'Low', 'Monitoring', 'market_intelligence', 'Monitoring', 'Low', 'New', NULL, '[{\"url\":\"https:\\/\\/www.prittleprattlenews.com\\/technology\\/practical-ai-applications-take-focus-as-rsk-business-solutions-heads-to-dubai-ai-festival-2026\\/\",\"title\":\"Practical AI Applications Take Focus as RSK Business Solutions Heads to Dubai AI Festival 2026 - Prittle Prattle News\",\"published_at\":\"2026-09-18\",\"excerpt\":\"RSK Business Solutions has announced its participation in Dubai AI Festival 2026, where the technology consultancy plans to demonstrate artificial intelligence applications designed for operational and business requirements.\",\"retrieved_at\":\"2026-10-01T12:54:17+00:00\",\"page_fetched\":false}]', '[\"RSK Business Solutions announced participation in Dubai AI Festival 2026.\",\"Its focus will be on demonstrating how organisations can apply AI to operational requirements with measurable business outcomes.\"]', '[\"Whether RSK is seeking AI vendors or partners\",\"Any specific project or budget\"]', '2026-09-18', '2026-09-18', 'b315f1faca6bf7eab65d0448fe5c6e1b9fa18f2d22d6e607e685d1d38313426a', '2026-10-01 12:54:58', '2026-10-01 12:54:58', NULL, NULL, '2026-10-01 12:54:58', '2026-10-01 12:54:58');
INSERT IGNORE INTO `g2g_company_opportunities` (`id`, `sub_institute_id`, `company_id`, `research_run_id`, `ingestion_source_id`, `product_name`, `title`, `category`, `signal_kind`, `observed_event`, `why_indicates_need`, `product_fit`, `relevant_offer_id`, `relevant_offer_name`, `recommended_action`, `priority`, `urgency`, `feed_section`, `qualification`, `confidence`, `review_status`, `review_notes`, `sources`, `confirmed_facts`, `unverified_claims`, `source_published_at`, `event_date`, `fingerprint`, `first_discovered_at`, `last_verified_at`, `reviewed_by`, `reviewed_at`, `created_at`, `updated_at`) VALUES ('6', '6', '6', '4', NULL, 'TRIZ Innovation — AI, Enterprise Intelligence & Digital Solutions', 'ShikshaNext selects 11 EdTech and AI solutions and moves to execution with state government systems', 'project', 'opportunity', 'ShikshaNext, a 3-year INR 170-crore multi-donor initiative, announced the next phase of its journey with the selection of 11 solutions across its EdTech ScaleX and EdTech Accelerator pillars, aiming to bring evidence-backed and emerging EdTech and AI solutions closer to classrooms and state government systems by 2029.', 'A funded, multi-donor education initiative moving from vision to execution and scaling selected EdTech/AI solutions into state government systems implies demand for education technology, learning analytics and AI-enabled solution integration capability.', 'Scholar Clone education technology (LMS, academic analytics, learning intelligence) and custom AI integrations/APIs map directly to scaling EdTech and AI solutions into classrooms and state systems.', NULL, NULL, 'Research the 11 selected solutions and the ScaleX/Accelerator partner list to identify where Scholar Clone or custom AI integration could complement or partner; approach the Managing Partner (Central Square Foundation) and initiative partners for partnership routes.', 'High', 'Within 90 days', 'immediate_action', 'Relevant Requirement Found', 'Medium', 'New', NULL, '[{\"url\":\"https:\\/\\/www.bignewsnetwork.com\\/news\\/279323856\\/shikshanext-introduces-11-edtech-and-ai-solutions-shaping-the-market-for-better-learning-outcomes-in-india\",\"title\":\"ShikshaNext Introduces 11 EdTech and AI Solutions, Shaping the Market for Better Learning Outcomes in India\",\"published_at\":\"2026-09-22\",\"excerpt\":\"ShikshaNext, the 3-year, INR 170-crore multi-donor initiative aimed at improving learning outcomes for children across India by leveraging EdTech and AI, today announced the next phase of its journey with the selection of 11 solutions across its EdTech ScaleX and EdTech Accelerator pillars.\",\"retrieved_at\":\"2026-10-02T05:06:08+00:00\",\"page_fetched\":false},{\"url\":\"https:\\/\\/www.business-standard.com\\/content\\/press-releases-ani\\/shikshanext-introduces-11-edtech-and-ai-solutions-shaping-the-market-for-better-learning-outcomes-in-india-126092200884_1.html\",\"title\":\"ShikshaNext Introduces 11 EdTech and AI Solutions, Shaping the Market for Better Learning Outcomes in India\",\"published_at\":\"2026-09-22\",\"excerpt\":\"New Delhi [India], September 22: ShikshaNext, the 3-year, INR 170-crore multi-donor initiative aimed at improving learning outcomes for children across India by leveraging EdTech and AI, today announced the next phase of its journey with the selection of 11 solutions across its EdTech ScaleX and EdT\",\"retrieved_at\":\"2026-10-02T05:06:08+00:00\",\"page_fetched\":false}]', '[\"ShikshaNext is a 3-year, INR 170-crore multi-donor initiative aimed at improving learning outcomes in India using EdTech and AI.\",\"It announced selection of 11 solutions across EdTech ScaleX and EdTech Accelerator pillars.\",\"It aims to bring EdTech and AI solutions closer to classrooms and state government systems by 2029.\",\"Founding Strategic Partners include the Michael & Susan Dell Foundation, Reliance Foundation and Gates Foundation, with Central Square Foundation as Managing Partner.\"]', '[\"Whether ShikshaNext or its partners have any open procurement, RFP or vendor onboarding process.\",\"Whether any budget is allocated to third-party AI\\/edtech vendors beyond the 11 selected solutions.\",\"Identity and capabilities of the 11 selected solutions.\"]', '2026-09-22', '2026-09-22', '492a5524b07e28696848a91e75c34bafbc121009bff5edf0bb80ea07819fd872', '2026-10-02 05:07:11', '2026-10-02 05:07:11', NULL, NULL, '2026-10-02 05:07:11', '2026-10-02 05:07:11');
