INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('6', '6', '3', 'https://www.bbc.com/news/articles/c8r6y4me2g6o', 'Google to fund Finnish AI with €13bn investment and nuclear power pact', 'bbc.com', 'Skip to contentSite searchHomeNewsSportBusinessTechnologyHealthCultureArtsTravelEarthAudioVideoLiveWeatherNewslettersGoogle picks Finland for its largest single investment in Europe9 September 2026ShareSaveAdd as preferred on GoogleJessica RawnsleyGetty ImagesGoogle will buy up to half the electricity produced by one of Finland\'s nuclear power plants as part of a record €13bn (£11bn; $15bn) investment in the country\'s AI infrastructure, the company announced.The US tech giant said the package would fund three new data centres, expand an existing site and support energy projects to power growing demand for AI services.\"This is Google\'s largest single investment in Europe and a testament to Finland\'s leadership in responsibly building AI infrastructure,\" the company said on Wednesday.\"Google\'s decision is a clear testament to our strengths,\" Finland\'s Prime Minister Petteri Orpo said in a statement.As part of the deal, Google signed a 22-year contract with Finnish utility Fortum to buy u', '2026-09-09', '2026-10-01 12:54:17', '1', '0', '2026-10-01 12:54:48', '2026-10-01 12:54:48');
