INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('15', '6', '3', 'https://www.storyboard18.com/digital/prime-focus-backed-brahma-ai-raises-150-million-at-2-billion-valuation-eyes-global-expansion-111171.htm', 'Prime Focus-backed Brahma AI raises $150 million at $2 billion valuation, eyes global expansion - Storyboard18', 'storyboard18.com', 'With DNEG providing exposure to high-end visual effects, animation and content creation, and Brahma AI developing an enterprise AI platform for audiovisual assets, Prime Focus is building two distinct technology-led businesses with applications extending across the global media ecosystem. [...] The company is being positioned separately from Prime Focus\' traditional media and entertainment operations. DNEG provides the group with a global presence in visual effects, animation and high-end content creation, while Brahma AI gives it exposure to the enterprise AI technology market.\n\nPrime Focus to retain about 66% economic ownership\n\nFollowing the financing, Prime Focus will remain the largest economic shareholder in Brahma AI. [...] Prime Focus Limited, which announced the fundraise on September 23, said Brahma AI has also received a further $100 million of investor demand and will evaluate increasing the size of the round to accommodate some or all of that interest.\n\nThe latest funding ', '2026-09-23', '2026-10-01 12:54:17', '0', '1', '2026-10-01 12:54:48', '2026-10-01 12:54:58');
INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('16', '6', '3', 'https://www.futuretravelexperience.com/2026/09/30-airlines-and-airports-nominated-for-fte-apac-pioneer-awards-2026-winners-to-be-announced-at-apex-fte-expo', 'Shortlists announced for FTE APAC Pioneer Awards 2026', 'futuretravelexperience.com', 'Air New Zealand’s adoption of ChatGPT Enterprise has also expanded its AI capabilities beyond individual experiments. Thousands of corporate employees have access to the technology, with teams developing custom GPTs to support collaboration, automate repetitive tasks and improve areas including customer service, planning and information access. This is helping establish AI as an everyday productivity tool across the organisation. [...] A major focus is the airline’s enterprise generative AI strategy. EVA Air has established a dedicated enterprise AI platform to support secure internal knowledge applications and is expanding the use of external generative AI tools alongside agent-based AI. An enterprise intelligent support system is also being developed as an employee assistant, while robotic process automation is enabling business teams to create their own workflows and reduce manual processes. [...] AI is being deployed across multiple operational use cases, including predictive maint', '2026-09-24', '2026-10-01 12:54:17', '0', '0', '2026-10-01 12:54:48', '2026-10-01 12:54:48');
INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('17', '6', '3', 'https://indianexpress.com/article/technology/artificial-intelligence/salesforce-ai-model-everything-announced-dreamforce-2026-10880785', 'From new AI CRM model to Air India team-up, everything announced at Dreamforce 2026 | Technology News - The Indian Express', 'indianexpress.com', '“We’ve built incredible teams in India. I think this is a huge opportunity for India. That is, we’re going to rebuild all of our enterprise systems to be AI-first, and I think these intelligent interfaces-they’re going to do some of the work, and then they’re going to need partners, trailblazers, and we have millions and millions of trailblazers in India. So I’m sure that they will be a key part of this incredible story,” Benioff was quoted as saying by PTI.\n\n© IE Online Media Services Pvt Ltd [...] Salesforce also launched AIforce, which lets customers carry over enterprise data housed in its products to any AI interface. The enterprise giant further said it is partnering with Air India, enabling the airline to leverage AI agents and other automation capabilities via Salesforce’s Agentforce platform.\n\nStory continues below.  Subscribe to see fewer ads. [...] AIforce\n\nAIforce helps customers bring enterprise data, workflows, permissions, security, etc., to any AI interface without havi', '2026-09-16', '2026-10-01 12:54:17', '0', '0', '2026-10-01 12:54:48', '2026-10-01 12:54:48');
INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('18', '6', '3', 'https://www.tribuneindia.com/news/business/vaia-expands-into-the-us-market-bringing-its-ai-intelligence-platform-to-american-financial-institutions', 'Vaia Expands into the US Market, Bringing Its AI Intelligence Platform to American Financial Institutions - The Tribune', 'tribuneindia.com', 'PNN\n\nBengaluru (Karnataka) [India], September 24: Vaia, an AI-powered intelligence platform for financial institutions, has announced its expansion into the United States to serve banks, investment firms, wealth managers and family offices, marking an important step in the company\'s global growth. The move comes as financial institutions increasingly look beyond experimental AI tools toward systems that can work across real investment, data, reporting and operational workflows. [...] “Taking technology built and refined in India into the hands of some of the world\'s most sophisticated financial institutions is an important milestone for us. But this is not simply about taking an Indian product to the US. We are building Vaia in the US as well, with local technology, product and commercial teams who understand the market deeply and can build alongside our clients. Our ambition is to bring together the best of both ecosystems and create a truly global financial AI company.” -', '2026-09-24', '2026-10-01 12:54:17', '0', '1', '2026-10-01 12:54:48', '2026-10-01 12:54:58');
INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('19', '6', '3', 'https://www.indiasnews.net/news/279282934/karnataka-eyes-over-66000-jobs-as-high-level-clearance-committee-approves-projects-worth-rs-29679-cr-priyank-kharge', 'Karnataka eyes over 66,000 jobs as High-Level Clearance Committee approves projects worth Rs 29,679 Cr: Priyank Kharge - India\'s News.Net', 'indiasnews.net', 'Bengaluru (Karnataka) [India], September 3 (ANI): Karnataka has approved investment projects worth Rs 29,679 crore with the potential to create more than 66,000 jobs, state Home Minister Priyank Kharge said on Thursday. In a post shared on X, Priyank Kharge said the projects were cleared at the 68th State High Level Clearance Committee (SHLCC) meeting chaired by Karnataka Chief Minister DK Shivakumar. \'At the 68th State High Level Clearance Committee (SHLCC) meeting chaired by the Hon\'ble @CMofKarnataka, investment projects worth Rs 29,679 crore were approved with the potential to create 66,000+ jobs,\' Kharge said. Highlighting some of the major investments, Priyank Kharge said Mahindra Aerostructures will invest Rs 2,300 crore to establish a facility for manufacturing aerospace parts and assemblies in Kolar, while Aequs Consumer Products will invest Rs 1,104 crore to expand manufacturing of components and assemblies for the electronics sector in Dharwad. \'From aerospace and electronic', '2026-09-03', '2026-10-01 12:54:17', '0', '0', '2026-10-01 12:54:48', '2026-10-01 12:54:48');
INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('20', '6', '3', 'https://www.indiasnews.net/news/279331868/minister-mb-patil-holds-talks-with-gan-siow-huang-singapore-minister-of-state-for-trade-and-industry', 'Minister MB Patil holds talks with Gan Siow Huang, Singapore Minister of State for Trade and Industry - India\'s News.Net', 'indiasnews.net', 'Bengaluru (Karnataka) [India], September 25 (ANI): CapitaLand Investment, a global real asset manager, is keen to expand its data centre capacity in Karnataka, in addition to the 42 MW data centre it is developing at International Tech Park Bangalore in Bengaluru, with an investment of approximately Rs 2,000 crore, Karnataka Minister for Large and Medium Industries MB Patil, who is visiting Singapore to attract investments to the State, said on Friday. In a media release following discussions with several companies, Patil said ST Telemedia Global Data Centres (STT GDC), a leading data centre platform with a significant presence in India, has expressed interest in further expanding its data centre presence in the State. The company is investing approximately Rs 5,000 crore to develop a 100 MW data centre campus on KIADB land in Devanahalli, he said. The Singapore Government has also been invited to participate as a partner country at the Global Investor Meet 2027 to be held next year, h', '2026-09-25', '2026-10-01 12:54:17', '0', '0', '2026-10-01 12:54:48', '2026-10-01 12:54:48');
INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('21', '6', '3', 'https://www.prnewswire.com/news-releases/keystone-to-launch-india-business-with-bengaluru-as-first-hub-plans-to-hire-talent--increase-workforce-over-next-two-years-302889844.html', 'Keystone To Launch India Business With Bengaluru As First Hub, Plans To Hire Talent & Increase Workforce Over Next Two Years - PR Newswire', 'prnewswire.com', '# Keystone To Launch India Business With Bengaluru As First Hub, Plans To Hire Talent & Increase Workforce Over Next Two Years. 25, 2026 /PRNewswire/ -- Keystone, a global advisory firm that guides the most critical technology and science-based platforms and ecosystems, today announced it is establishing Keystone India, with Bengaluru as its first hub in the country. The company plans to hire talent and expand its workforce in India over the next two years. Keystone India will expand the firm\'s global presence, navigate India\'s market structure, regulatory complexity, litigation exposure and platform risk. The Bengaluru team will support global technology companies including Microsoft and Meta, financial services firms like Goldman Sachs, as well as India\'s largest law firms and global enterprises, helping each of these entities navigate this moment of AI disruption, as well as India\'s distinctive market structure, regulatory environment and technology ecosystems.', '2026-09-25', '2026-10-01 12:54:17', '0', '1', '2026-10-01 12:54:48', '2026-10-01 12:54:58');
INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('22', '6', '3', 'https://m.economictimes.com/tech/technology/karnataka-identifies-land-for-space-manufacturing-cluster-near-bengaluru/articleshow/133932676.cms', 'Karnataka identifies land for space manufacturing cluster near Bengaluru - The Economic Times', 'm.economictimes.com', 'Nifty23,635.10-144.06. Sensex75,577.58-555.23. GE T&D India 4,750.00382.81. New India Assurance205.22-25.98. Gold (MCX) (Rs/10g.) (Rs/10g.)\")1,52,497.00-321.00. Business NewsTechTech & InternetKarnataka identifies land for space manufacturing cluster near Bengaluru. # Karnataka identifies land for space manufacturing cluster near Bengaluru. ### Synopsis. The proposed space park will support space technology manufacturing, assembly, integration, testing, research and innovation, and bring together startups, micro, small and medium enterprises (MSMEs), larger companies, research institutions and technology providers, IT/BT secretary Manjula N said in a statement. Karnataka has identified land in Hoskote near Bengaluru for a proposed space manufacturing cluster and is preparing a detailed project report.The proposed space park will support space technology manufacturing, assembly, integration, testing, research and innovation, and bring together startups, micro, small and medium enterpris', '2026-09-08', '2026-10-01 12:54:17', '0', '0', '2026-10-01 12:54:48', '2026-10-01 12:54:48');
