INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('24', '6', '3', 'https://www.indiasnews.net/news/279280815/q-oak-interiors-opens-larger-bengaluru-factory-plans-hsr-layout-experience-centre', 'Q Oak Interiors Opens Larger Bengaluru Factory, Plans HSR Layout Experience Centre - India\'s News.Net', 'indiasnews.net', '## Q Oak Interiors Opens Larger Bengaluru Factory, Plans HSR Layout Experience Centre. Bengaluru (Karnataka) [India], September 2: Q Oak Interiors has opened a larger manufacturing facility in JP Nagar, 7th Phase, Bengaluru South, increasing its capacity to produce modular kitchens, wardrobes and customised furniture for residential interior projects across Bengaluru. It replaces/expands the company\'s earlier manufacturing unit and raises monthly production capacity from 50 projects to 100+ projects. According to the company, the expansion was needed to handle a growing number of full-home interior projects while retaining direct control over manufacturing, finishing and quality checks. \"The larger facility gives us the capacity and machinery to manage these details more closely.\". The company is now planning another experience centre in HSR Layout, with an opening targeted for the end of 2026. With the new factory, Q Oak Interiors is preparing to take on a larger volume of residential', '2026-09-02', '2026-10-01 12:54:17', '0', '0', '2026-10-01 12:54:48', '2026-10-01 12:54:48');
