INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('37', '6', '4', 'https://indianexpress.com/article/technology/tech-news-technology/synopsys-openai-strike-deal-to-develop-ai-model-for-chip-design-work-10901677', 'Synopsys, OpenAI strike deal to develop AI model for chip design work | Technology News - The Indian Express', 'indianexpress.com', 'skip to content\nAdvertisement\nSynopsys, OpenAI strike deal to develop AI model for chip design work\nOpenAI\'s model will learn how to use Synopsys software tools to help engineers ​work through ​the various trade-offs and optimizations.\nBy: Reuters2 min readNew DelhiOct 1, 2026 09:24 AM IST\nThe Daybreak initiative has been expanded into two tiers – Daybreak Blue and Daybreak Red. (Express Image)\nMake us preferred source on Google\nWhatsapp\ntwitter\nFacebook\nReddit\nPRINT\nSynopsys, a maker of software used in designing computing chips, said on Wednesday that it has struck a deal to share revenue with OpenAI as the two develop an AI model for the chip business.\nGPT-Synopsys, as the model will be called, will be specifically trained and tuned to take on chip design tasks, which start with a description of ⁠the ​chip’s circuits in a code-like language and span to determining how to lay out billions of transistors on a small square of silicon.\nOpenAI’s model will learn how to use Synopsys softw', '2026-10-01', '2026-10-02 05:06:08', '1', '0', '2026-10-02 05:06:57', '2026-10-02 05:06:57');
