INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('39', '6', '4', 'http://electronics.economictimes.indiatimes.com/news/semiconductors/openai-says-deepening-cooperation-with-south-korean-samsung-on-ai-chips-enterprise-services/133957867', 'OpenAI Expands Collaboration with Samsung on AI Chips and Enterprise AI Services, ETElectronicsWorld', 'electronics.economictimes.indiatimes.com', 'NEW DELHI: OpenAI is deepening its cooperation with Samsung Electronics as the ChatGPT maker develops proprietary artificial intelligence chips, expanding ties with the South Korean technology giant across semiconductors and enterprise AI services. [...] ### India’s manufacturing sector stands at a critical inflection point. After years of policy push, infrastructure investments, and growing global interest, the country is no longer just an emerging manufacturing destination.\n\nET Global Manufacturing Conclave & Awards 2026\n\n Semiconductors\n 2 minRead\n\n# OpenAI says deepening cooperation with South Korean Samsung on AI chips, enterprise services [...] In June, OpenAI unveiled its first custom AI chip, named Jalapeno, designed alongside Broadcom to support AI inference workloads and slated for manufacturing by Taiwan Semiconductor Manufacturing Company.\nLast year, Samsung Electronics and SK Hynix signed letters of intent to supply memory chips for OpenAI\'s Stargate data center infrastruc', '2026-09-10', '2026-10-02 05:06:08', '0', '0', '2026-10-02 05:06:57', '2026-10-02 05:06:57');
