INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('41', '6', '4', 'https://www.futuretravelexperience.com/2026/09/30-airlines-and-airports-nominated-for-fte-apac-pioneer-awards-2026-winners-to-be-announced-at-apex-fte-expo', 'Shortlists announced for FTE APAC Pioneer Awards 2026', 'futuretravelexperience.com', 'Air New Zealand’s adoption of ChatGPT Enterprise has also expanded its AI capabilities beyond individual experiments. Thousands of corporate employees have access to the technology, with teams developing custom GPTs to support collaboration, automate repetitive tasks and improve areas including customer service, planning and information access. This is helping establish AI as an everyday productivity tool across the organisation. [...] A major focus is the airline’s enterprise generative AI strategy. EVA Air has established a dedicated enterprise AI platform to support secure internal knowledge applications and is expanding the use of external generative AI tools alongside agent-based AI. An enterprise intelligent support system is also being developed as an employee assistant, while robotic process automation is enabling business teams to create their own workflows and reduce manual processes. [...] AI is being deployed across multiple operational use cases, including predictive maint', '2026-09-24', '2026-10-02 05:06:08', '0', '0', '2026-10-02 05:06:57', '2026-10-02 05:06:57');
INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('42', '6', '4', 'https://indianexpress.com/article/technology/artificial-intelligence/salesforce-ai-model-everything-announced-dreamforce-2026-10880785', 'From new AI CRM model to Air India team-up, everything announced at Dreamforce 2026 | Technology News - The Indian Express', 'indianexpress.com', '“We’ve built incredible teams in India. I think this is a huge opportunity for India. That is, we’re going to rebuild all of our enterprise systems to be AI-first, and I think these intelligent interfaces-they’re going to do some of the work, and then they’re going to need partners, trailblazers, and we have millions and millions of trailblazers in India. So I’m sure that they will be a key part of this incredible story,” Benioff was quoted as saying by PTI.\n\n© IE Online Media Services Pvt Ltd [...] Salesforce also launched AIforce, which lets customers carry over enterprise data housed in its products to any AI interface. The enterprise giant further said it is partnering with Air India, enabling the airline to leverage AI agents and other automation capabilities via Salesforce’s Agentforce platform.\n\nStory continues below.  Subscribe to see fewer ads. [...] AIforce\n\nAIforce helps customers bring enterprise data, workflows, permissions, security, etc., to any AI interface without havi', '2026-09-16', '2026-10-02 05:06:08', '0', '0', '2026-10-02 05:06:57', '2026-10-02 05:06:57');
INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('43', '6', '4', 'https://www.peoplematters.in/news/leadership/meta-hires-indian-origin-mongodb-ceo-to-lead-new-enterprise-ai-business-52391', 'Meta hires Indian-origin MongoDB CEO to lead new enterprise AI business', 'peoplematters.in', 'Ad banner\n\nAd banner\n\nLoading... [...] In a statement released by Meta, Desai said AI would fundamentally reshape how organisations innovate, serve customers and run operations over the coming years. He added that Meta Enterprise Platform would focus on turning the company\'s AI technology stack into products and services businesses can deploy at scale.\n\nHis appointment places an experienced enterprise technology executive at the centre of Meta’s commercial AI strategy as competition intensifies among major technology companies. [...] According to Meta, the platform will package its AI technologies into products and services that organisations can deploy across operations, customer engagement and business workflows.\n\n## Meta sharpens focus on enterprise AI\n\nThe launch signals Meta’s intention to move beyond consumer-facing AI products and build a stronger position in the enterprise technology market.\n\nAccording to the company, the Meta Enterprise Platform will offer access to technologi', '2026-09-29', '2026-10-02 05:06:08', '0', '0', '2026-10-02 05:06:57', '2026-10-02 05:06:57');
