INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('45', '6', '4', 'https://www.edexlive.com/news/us-ambassador-sergio-gor-launches-trust-fellowship-for-collaboration-on-critical-technologies-2', 'US Ambassador Sergio Gor launches TRUST Fellowship for collaboration', 'edexlive.com', 'The Ambassador also announced an expansion of the US Commercial Service presence in Bengaluru to provide greater support to American companies seeking to expand their operations in South India.\n\nThe expanded services will include export counselling, market intelligence, and assistance in connecting American companies with vetted local partners. [...] “American enterprises need stronger support, sharper market intelligence, and wider doors in this market. That is precisely what this expansion delivers. It means more American exports. It means more American jobs. And it means American companies taking a direct stake in Bengaluru’s growth engine,” Gor said.', '2026-09-11', '2026-10-02 05:06:08', '0', '0', '2026-10-02 05:06:57', '2026-10-02 05:06:57');
