INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('47', '6', '4', 'https://newskarnataka.com/business/globe-bets-on-ai-and-data-centres-for-growth/29092026', 'Globe bets on AI and data centres for growth | News Karnataka', 'newskarnataka.com', 'That capacity could increase substantially over the following three years. Plans involving new facilities and expansion of existing sites are expected to take total capacity to about 124 MW.\n\nThe expansion reflects expectations that AI and cloud computing will drive significantly higher demand for data-centre infrastructure.\n\nCruz said data traffic in the Philippines could increase by three to five times over the next few years as AI adoption accelerates. [...] ## Globe faces competition from PLDT and Converge\n\nGlobe’s expansion is taking place in an increasingly competitive domestic market.\n\nRival PLDT Inc. has established a major presence through its data-centre subsidiary VITRO Inc., which is also pursuing expansion.\n\nVITRO is seeking to raise as much as 24.2 billion pesos, or approximately $387 million, through a real estate investment trust initial public offering to support its data-centre ambitions. [...] These include its undersea cable connections to developed Asian markets, r', '2026-09-30', '2026-10-02 05:06:08', '0', '0', '2026-10-02 05:06:58', '2026-10-02 05:06:58');
INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('48', '6', '4', 'https://www.livemint.com/companies/news/karnataka-clears-investments-from-toyota-mahindra-hero-future-energies-and-others-worth-rs-29-679-crore-will-create-o-11788408988016.html', 'Karnataka clears investments from Toyota, Mahindra, and others worth ₹29,679 crore, will create over 66,000 jobs | Company Business News', 'livemint.com', 'According to Priyank Kharge, Karnataka’s Minister for Home Affairs, Information Technology, Biotechnology, and E-Governance, the investments reflected Karnataka\'s growing strength across sectors, including aerospace, electronics manufacturing, digital infrastructure and business intelligence. [...] \"From aerospace and electronics manufacturing to digital infrastructure and business intelligence, Karnataka continues to be one of India’s most trusted and preferred destinations for business and investment,\" he said in a post on X.\n\nDuring the meeting, the Chief Minister directed the Finance Department to thoroughly scrutinise project reports submitted for industrial licences and said a pre-clearance audit should be made mandatory for projects. [...] Also Read | Karnataka CM Shivakumar announces India\'s first govt-backed AI university\n\nHe also instructed officials to constitute a new audit team and ensure strict compliance with the provisions of the industrial policy while taking steps to ', '2026-09-03', '2026-10-02 05:06:08', '0', '0', '2026-10-02 05:06:58', '2026-10-02 05:06:58');
INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('49', '6', '4', 'https://www.deccanchronicle.com/business/companies/eazy-launches-ai-powered-business-intelligence-and-hrms-platforms-1991951', 'Eazy Launches AI-Powered Business Intelligence and HRMS Platforms', 'deccanchronicle.com', 'Top\n\n Home\n South\n\n  + Andhra Pradesh\n  + Telangana\n  + Tamil Nadu\n  + Karnataka\n  + Keralam\n World\n\n  + NRI\n Nation\n\n  + Youth\n Entertainment\n\n  + Sholay\n  + Tollywood\n  + Bollywood\n  + Sandalwood\n  + Kollywood\n  + Mollywood\n  + Hollywood\n  + Movie Reviews\n  + Television\n  + Music\n  + Theatre\n  + OTT\n Sports [...] Eazy, a leading enterprise technology company, has announced the expansion of its technology ecosystem at NEXUS, its flagship business and innovation showcase in Delhi. The company has added new HRMS and Business Intelligence platforms to its portfolio, while enhancing its existing POS, CRM and Sales Force Automation (SFA) offerings to create a more integrated technology stack spanning sales, retail, finance and other core business functions. [...] At the centre of this expansion are Eazy Business Analytics and Eazy HRMS, reflecting Eazy’s focus on helping businesses bring greater intelligence, integration and visibility into everyday operations. Eazy Business Analytics brin', '2026-09-30', '2026-10-02 05:06:08', '0', '0', '2026-10-02 05:06:58', '2026-10-02 05:06:58');
INSERT IGNORE INTO `g2g_research_sources` (`id`, `sub_institute_id`, `research_run_id`, `url`, `title`, `domain`, `snippet`, `published_at`, `retrieved_at`, `page_fetched`, `cited`, `created_at`, `updated_at`) VALUES ('50', '6', '4', 'https://www.passionateinmarketing.com/nec-india-and-wingarc1st-expand-strategic-partnership-to-bring-data-empowerment-solutions-to-india', 'NEC India and WingArc1st Expand Strategic Partnership', 'passionateinmarketing.com', 'The partnership will address opportunities across Enterprise, Financial Services, Manufacturing, and Public Sector/Government, reflecting the broad applicability of data and analytics technologies as organizations seek to improve operational efficiency, strengthen business intelligence, and support informed decision-making. [...] NEC India and WingArc1st Expand Strategic Partnership to Bring Data Empowerment Solutions to India\n\nIndia, 22nd September 2026: NEC Corporation India Pvt. Ltd. and WingArc1st Inc. today announced the expansion of their strategic collaboration in India following the execution of a Master Distribution Agreement (MDA) between NEC Corporation India Pvt. Ltd. and WingArc Singapore Pte. Ltd. (“WingArc Singapore”), a WingArc1st group company. [...] The expansion into India builds on this established foundation. NEC India brings extensive experience working with enterprise, government, and public-sector organizations, together with a broad technology and digital trans', '2026-09-22', '2026-10-02 05:06:08', '0', '0', '2026-10-02 05:06:58', '2026-10-02 05:06:58');
